-- An Append cannot project, so a select list or UPDATE computed over an
-- inheritance tree runs in a Result above its members, which return the
-- columns read; the Result stays above a lone member. A partitioned
-- table's members compute it themselves. A RETURNING list prints under the
-- first member's name, a locked parent's members return their tableoid,
-- and ONLY writes the parent alone.
CREATE TABLE ip610 (a int, v int);
CREATE TABLE ip610_1 (CHECK (a < 10)) INHERITS (ip610);
CREATE TABLE ip610_2 (CHECK (a >= 10)) INHERITS (ip610);
INSERT INTO ip610 VALUES (1, 1);
INSERT INTO ip610_1 VALUES (2, 2), (3, 3);
INSERT INTO ip610_2 VALUES (12, 12);
EXPLAIN (COSTS OFF) SELECT a + 1 FROM ip610;
EXPLAIN (COSTS OFF) SELECT a + 1 FROM ip610 ORDER BY 1 LIMIT 2;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) SELECT a + 1 FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1 FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT v, a FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a, a FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a FROM ip610 ORDER BY v;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1 FROM ip610 ORDER BY 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT sum(a + 1) FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1, count(*) FROM ip610 GROUP BY 1;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a, 1 FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT ip610 FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT tableoid, a FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT tableoid::regclass, a FROM ip610;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a FROM ip610 FOR UPDATE;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1 FROM ip610 FOR UPDATE;
EXPLAIN (COSTS OFF) UPDATE ip610 SET v = 0 WHERE a = 3;
EXPLAIN (COSTS OFF) UPDATE ip610 SET v = 0;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE ip610 SET v = v + 1;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE ip610 SET v = a + v WHERE a = 2;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE ip610 SET v = 2, a = v RETURNING a;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE ip610 x SET v = x.a * 2 RETURNING x.*;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM ip610 WHERE a > 3 RETURNING v;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) UPDATE ip610 SET v = 0 WHERE a > 2;
EXPLAIN (COSTS OFF) UPDATE ONLY ip610 SET v = 0;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE ONLY ip610 SET v = 0;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM ONLY ip610 WHERE a = 1 RETURNING *;
UPDATE ip610 SET v = v + 1 WHERE a > 1;
UPDATE ONLY ip610 SET v = 100;
SELECT tableoid::regclass, * FROM ip610 ORDER BY a;
SELECT a FROM ip610 ORDER BY a FOR UPDATE;
CREATE TABLE iq610 (a int, v int, CHECK (a < 0) NO INHERIT);
CREATE TABLE iq610_1 (CHECK (a < 10)) INHERITS (iq610);
CREATE TABLE iq610_2 (CHECK (a >= 10)) INHERITS (iq610);
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1 FROM iq610 WHERE a = 5;
EXPLAIN (VERBOSE, COSTS OFF) SELECT a + 1 FROM iq610 WHERE a > 5;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE iq610 SET v = 1 WHERE a = 5;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM iq610 WHERE a = 5;
CREATE TABLE pt610 (id int, v int) PARTITION BY RANGE (id);
CREATE TABLE pt610_1 PARTITION OF pt610 FOR VALUES FROM (1) TO (10);
CREATE TABLE pt610_2 PARTITION OF pt610 FOR VALUES FROM (10) TO (20);
EXPLAIN (VERBOSE, COSTS OFF) SELECT id + 1 FROM pt610;
EXPLAIN (VERBOSE, COSTS OFF) UPDATE pt610 SET v = 1 RETURNING *;
EXPLAIN (VERBOSE, COSTS OFF) DELETE FROM pt610 x WHERE id = 3 RETURNING x.v + 1, id;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM pt610 FOR UPDATE;
EXPLAIN (VERBOSE, COSTS OFF) SELECT * FROM pt610 WHERE id = 3 FOR SHARE;
